sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.trackmed-widget {
    margin-bottom: 30px;
    width: 100%;
}

.content-card {
  background: #fff;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
}
.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  padding-bottom: 14px;
  border-bottom: 2px solid #f1f5f9;
}

.card-header h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: #1a2332;
}

.card-header h3 i {
  color: #1a73e8;
}

.view-all-link {
  font-size: 13px;
  color: #1a73e8;
  text-decoration: none;
}

.view-all-link:hover {
  text-decoration: underline;
}

/* Summary */

.alert-summary-items {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 20px;
}

.alert-summary-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #f8fafc;
  padding: 12px 14px;
  border-radius: 10px;
}

.alert-icon-wrap {
  width: 36px;
  height: 36px;
  border-radius: 8px;

  display: flex;
  justify-content: center;
  align-items: center;
}

.high-bg {
  background: #fee2e2;
  color: #dc2626;
}

.medium-bg {
  background: #fef3c7;
  color: #d97706;
}

.low-bg {
  background: #dcfce7;
  color: #16a34a;
}

.alert-summary-label {
  flex: 1;
  font-size: 14px;
  color: #374151;
}

.alert-summary-count {
  font-size: 24px;
  font-weight: 800;
}

.high-count {
  color: #dc2626;
}

.medium-count {
  color: #d97706;
}

.low-count {
  color: #16a34a;
}

/* Recent Alerts */

.recent-alerts-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.recent-alert-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #f8fafc;
  padding: 10px;
  border-radius: 8px;
}

.alert-priority-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.dot-high {
  background: #dc2626;
}

.dot-medium {
  background: #d97706;
}

.dot-low {
  background: #16a34a;
}

.alert-details {
  flex: 1;
}

.alert-patient {
  font-size: 13px;
  font-weight: 600;
  color: #1a2332;
}

.alert-desc {
  font-size: 12px;
  color: #64748b;
}

.alert-time {
  font-size: 12px;
  color: #94a3b8;
}

.alert-badge {
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 700;
}

.badge-high {
  background: #fee2e2;
  color: #dc2626;
}

.badge-medium {
  background: #fef3c7;
  color: #d97706;
}

.badge-low {
  background: #dcfce7;
  color: #16a34a;
}

